#include <zephyr/ztest.h>
#include <zephyr/sys/cbprintf.h>
#include <zephyr/sys/cbprintf_package.h>
#include <stdbool.h>

#define OUT_BUF_SIZE 256
#define PKG_BUF_SIZE (OUT_BUF_SIZE + sizeof(void *) * 20)

static uint8_t out_buf[OUT_BUF_SIZE];
static char cmp_buf[OUT_BUF_SIZE];
static uint8_t pkg_buf[PKG_BUF_SIZE];

struct buf_desc {
	uint8_t *buf;
	uint16_t len;
	uint16_t size;
};

static int out_func(int c, void *ctx)
{
	struct buf_desc *desc = (struct buf_desc *)ctx;

	if (desc->len < desc->size) {
		desc->buf[desc->len++] = (uint8_t)c;
		return c;
	}

	return -1;
}

static void reset_buf(struct buf_desc *desc)
{
	desc->len = 0;
	if (desc->size > 0) {
		desc->buf[0] = '\0';
	}
}

static void unpack(const char *fmt, char *buf, size_t size)
{
	struct buf_desc desc = { .buf = (uint8_t *)buf, .size = size };

	reset_buf(&desc);
	cbprintf_unpack(pkg_buf, fmt, out_func, &desc);
	if (desc->len < desc->size) {
		desc->buf[desc->len] = '\0';
	} else {
		desc->buf[desc.size - 1] = '\0';
	}
}

static void compare(const char *fmt, ...)
{
	struct buf_desc buf = { .buf = out_buf, .size = sizeof(out_buf) };
	va_list ap;

	unpack(fmt, (char *)buf.buf, buf.size);

	va_start(ap, fmt);
	vsnprintf(cmp_buf, sizeof(cmp_buf), fmt, ap);
	va_end(ap);

	zassert_equal(strcmp((char *)buf.buf, cmp_buf), 0, "unpack: Expected: %s, got: %s",
		      cmp_buf, (char *)buf.buf);
}

static void package(const char *fmt, ...)
{
	va_list ap;

	va_start(ap, fmt);
	(void)cbprintf_package(pkg_buf, sizeof(pkg_buf), fmt, ap);
	va_end(ap);
}

/* Test various combinations of arguments. */
ZTEST(cbprintf_package, test_cbprintf_package)
{
	/* No arguments */
	package("test");
	compare("test");

	/* Standard integer types */
	package("test %d %i %u %x", 1, -2, 3, 0xa);
	compare("test %d %i %u %x", 1, -2, 3, 0xa);

	/* char types */
	package("test %hhd %hhi %hhu %hhx", (char)1, (char)-2, (unsigned char)3, (unsigned char)0xa);
	compare("test %hhd %hhi %hhu %hhx", (char)1, (char)-2, (unsigned char)3, (unsigned char)0xa);

	/* short types */
	package("test %hd %hi %hu %hx", (short)1, (short)-2, (unsigned short)3,
		(unsigned short)0xa);
	compare("test %hd %hi %hu %hx", (short)1, (short)-2, (unsigned short)3,
		(unsigned short)0xa);

	/* Long integer types */
	package("test %ld %li %lu %lx", 1L, -2L, 3L, 0xaL);
	compare("test %ld %li %lu %lx", 1L, -2L, 3L, 0xaL);

	/* Long long integer types */
	package("test %lld %lli %llu %llx", 1LL, -2LL, 3LL, 0xaLL);
	compare("test %lld %lli %llu %llx", 1LL, -2LL, 3LL, 0xaLL);

	/* String and char */
	package("test %s %c", "string", 'c');
	compare("test %s %c", "string", 'c');

	/* Pointer */
	package("test %p", (void *)0x1234);
	compare("test %p", (void *)0x1234);

#ifdef CONFIG_CBPRINTF_FP_SUPPORT
	/* Double */
	package("test %f", 1.23);
	compare("test %f", 1.23);

	/* Long double */
	package("test %Lf", 1.23L);
	compare("test %Lf", 1.23L);
#endif

	/* Mix */
	package("test %d %s %c %p %lld", 1, "str", 'c', (void *)0x4321, 0xabcdLL);
	compare("test %d %s %c %p %lld", 1, "str", 'c', (void *)0x4321, 0xabcdLL);
}
